  cloudGroups:[{"id":"cloud-identity","title":"Identity and access","summary":"Know which database and account the connection belongs to.","ids":["personal-identity","saved-cloud-credentials","cloud-cutover","restored-account"]},{"id":"cloud-transfers","title":"Transfers and snapshots","summary":"Move saved changes and keep a recovery starting point.","ids":["automatic-backup","recovery-chain","cloud-files","byte-backup-client","personal-snapshot","log-segments","blob-transfers","cloud-destinations"]},{"id":"cloud-status","title":"Cleanup and status","summary":"Retire covered history and see what has been saved.","ids":["relay-trim","snapshot-status","cloud-usage","prod-recovery"]},{"id":"cloud-shared","title":"Shared transport","summary":"Carry shared definitions and changes between devices.","ids":["signed-schema","owned-write-mirror","frontier","owner-device-sync"]}],
